with filtered_accounts as (select *, round(balance, 0) as balance_rounded from accounts where customer_id = 21 and status in ('FROZEN', 'OPEN', 'CLOSED')), agg as (select status, min(opened_date) as min_opened_date, round(avg(balance_rounded), 2) as avg_balance_rounded from filtered_accounts group by status) select status, min_opened_date, avg_balance_rounded from agg where avg_balance_rounded < 31;
